begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
select has_function('public','world_npc_memory_embedding_accept',array['uuid','uuid','uuid','text','text','integer','extensions.vector','text','jsonb','text'],'receipt-gated acceptance RPC exists');
select ok(not has_function_privilege('service_role','public.world_npc_memory_embedding_complete(uuid,uuid,uuid,text,text,integer,extensions.vector,text,jsonb,text)','EXECUTE'),'service cannot call generic completion');
select ok(not has_function_privilege('authenticated','public.world_npc_memory_embedding_accept(uuid,uuid,uuid,text,text,integer,extensions.vector,text,jsonb,text)','EXECUTE'),'client cannot accept embeddings');
select ok(has_function_privilege('service_role','public.world_npc_memory_embedding_accept(uuid,uuid,uuid,text,text,integer,extensions.vector,text,jsonb,text)','EXECUTE'),'service can call receipt-gated acceptance');
insert into auth.users(id,email,role,aud) values ('20100000-0000-4000-8000-000000000001','embedding-accept@test','authenticated','authenticated');
set local role authenticated; set local request.jwt.claim.role='authenticated'; set local request.jwt.claim.sub='20100000-0000-4000-8000-000000000001'; select public.create_tavern();
create temporary table pg_temp.f as select (x#>>'{save,id}')::uuid save_id,(x->'roster'->0->>'instanceId')::uuid instance_id,(x->'roster'->0->>'npcId')::uuid npc_id,(x->'roster'->0->>'versionId')::uuid version_id,(x#>>'{save,revision}')::bigint revision from (select public.npc_bar_snapshot() x) q; grant select on pg_temp.f to service_role; reset role;
insert into private.world_npc_memory_embedding_profiles(id,processor_version,model,dimensions) values ('20100000-0000-4000-8000-000000000101','npc-embedding-accept-v1','accept-model',3);
set local role service_role; set local request.jwt.claim.role='service_role'; select public.world_npc_memory_embedding_profile_activate('20100000-0000-4000-8000-000000000101'); reset role;
insert into private.world_npc_dialogue_turns(id,save_id,instance_id,npc_id,version_id,actor_id,message,input_sequence,source_revision,day_number,status,lease_until,result,completed_at)
select id,save_id,instance_id,npc_id,version_id,'20100000-0000-4000-8000-000000000001',msg,seq,revision,1,'completed',clock_timestamp(),'{}',clock_timestamp() from pg_temp.f cross join (values
 ('20100000-0000-4001-8000-000000000001'::uuid,'a',0),('20100000-0000-4001-8000-000000000002'::uuid,'b',1),('20100000-0000-4001-8000-000000000003'::uuid,'c',2),('20100000-0000-4001-8000-000000000004'::uuid,'d',3),('20100000-0000-4001-8000-000000000005'::uuid,'e',4)
) v(id,msg,seq);
select private.world_npc_memory_register_source('dialogue_turn',id) from (values ('20100000-0000-4001-8000-000000000001'::uuid),('20100000-0000-4001-8000-000000000002'::uuid),('20100000-0000-4001-8000-000000000003'::uuid),('20100000-0000-4001-8000-000000000004'::uuid),('20100000-0000-4001-8000-000000000005'::uuid)) v(id);
set local role service_role; set local request.jwt.claim.role='service_role'; select public.world_npc_memory_embedding_schedule(5);
create temporary table pg_temp.c1 as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim;
create temporary table pg_temp.p1 as select public.world_npc_memory_embedding_plan((claim->>'id')::uuid,(claim->>'fence')::uuid) plan from pg_temp.c1;
select throws_ok(format('select public.world_npc_memory_embedding_accept(%L,%L,%L,%L,%L,3,%L::extensions.vector,%L,%L::jsonb)',(select claim->>'id' from pg_temp.c1),(select claim->>'fence' from pg_temp.c1),'20100000-0000-4000-8000-000000000101',(select plan->>'inputHash' from pg_temp.p1),'accept-model','[1,0,0]','r1','{"promptTokens":1,"totalTokens":1}'),'PT409',null,'success without a receipt is rejected');
select public.world_npc_memory_embedding_prepare_dispatch((claim->>'id')::uuid,(claim->>'fence')::uuid) from pg_temp.c1;
select throws_ok(format('select public.world_npc_memory_embedding_accept(%L,%L,%L,%L,%L,3,%L::extensions.vector,%L,%L::jsonb)',(select claim->>'id' from pg_temp.c1),(select claim->>'fence' from pg_temp.c1),'20100000-0000-4000-8000-000000000101',(select plan->>'inputHash' from pg_temp.p1),'accept-model','[1,0,0]','r1','{"promptTokens":1,"totalTokens":1}'),'PT409',null,'prepared receipt cannot accept success');
select public.world_npc_memory_embedding_mark_dispatched((claim->>'id')::uuid,(claim->>'fence')::uuid) from pg_temp.c1;
select is((select public.world_npc_memory_embedding_accept((claim->>'id')::uuid,(claim->>'fence')::uuid,'20100000-0000-4000-8000-000000000101',plan->>'inputHash','accept-model',3,'[1,0,0]'::extensions.vector,'r1','{"promptTokens":1,"totalTokens":1}'::jsonb)->>'status' from pg_temp.c1 cross join pg_temp.p1),'completed','marked receipt permits exact success');
select is((select public.world_npc_memory_embedding_accept((claim->>'id')::uuid,(claim->>'fence')::uuid,'20100000-0000-4000-8000-000000000101',plan->>'inputHash','accept-model',3,'[1,0,0]'::extensions.vector,'r1','{"promptTokens":1,"totalTokens":1}'::jsonb)->>'status' from pg_temp.c1 cross join pg_temp.p1),'reused','exact accepted replay is retained');
select throws_ok(format('select public.world_npc_memory_embedding_accept(%L,%L,%L,%L,%L,3,%L::extensions.vector,%L,%L::jsonb)',(select claim->>'id' from pg_temp.c1),(select claim->>'fence' from pg_temp.c1),'20100000-0000-4000-8000-000000000101',(select plan->>'inputHash' from pg_temp.p1),'accept-model','[0,1,0]','r1','{"promptTokens":1,"totalTokens":1}'),'PT409',null,'divergent accepted replay is rejected');
create temporary table pg_temp.c2 as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim; create temporary table pg_temp.p2 as select public.world_npc_memory_embedding_plan((claim->>'id')::uuid,(claim->>'fence')::uuid) plan from pg_temp.c2;
select is((select public.world_npc_memory_embedding_accept((claim->>'id')::uuid,(claim->>'fence')::uuid,'20100000-0000-4000-8000-000000000101',plan->>'inputHash',null,null,null,null,'{}'::jsonb,'provider_timeout')->>'status' from pg_temp.c2 cross join pg_temp.p2),'failed','no-receipt pre-dispatch failure remains terminalizable');
create temporary table pg_temp.c3 as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim; create temporary table pg_temp.p3 as select public.world_npc_memory_embedding_plan((claim->>'id')::uuid,(claim->>'fence')::uuid) plan from pg_temp.c3; select public.world_npc_memory_embedding_prepare_dispatch((claim->>'id')::uuid,(claim->>'fence')::uuid) from pg_temp.c3; select public.world_npc_memory_embedding_recover_dispatch((claim->>'id')::uuid,(claim->>'fence')::uuid) from pg_temp.c3;
select throws_ok(format('select public.world_npc_memory_embedding_accept(%L,%L,%L,%L,%L,3,%L::extensions.vector,%L,%L::jsonb)',(select claim->>'id' from pg_temp.c3),(select claim->>'fence' from pg_temp.c3),'20100000-0000-4000-8000-000000000101',(select plan->>'inputHash' from pg_temp.p3),'accept-model','[1,0,0]','r3','{"promptTokens":1,"totalTokens":1}'),'PT409',null,'terminalize-only receipt rejects success');
select is((select public.world_npc_memory_embedding_accept((claim->>'id')::uuid,(claim->>'fence')::uuid,'20100000-0000-4000-8000-000000000101',plan->>'inputHash',null,null,null,null,'{}'::jsonb,'provider_timeout')->>'status' from pg_temp.c3 cross join pg_temp.p3),'failed','terminalize-only receipt still permits failure');
create temporary table pg_temp.c4 as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim;
select throws_ok(format('select public.world_npc_memory_complete(%L,%L,%L::jsonb,null)',(select claim->>'id' from pg_temp.c4),(select claim->>'fence' from pg_temp.c4),'[]'),'PT409',null,'generic zero-artifact completion cannot bypass the embedding receipt path');
create temporary table pg_temp.c5 as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim;
create temporary table pg_temp.p5 as select public.world_npc_memory_embedding_plan((claim->>'id')::uuid,(claim->>'fence')::uuid) plan from pg_temp.c5;
select public.world_npc_memory_embedding_prepare_dispatch((claim->>'id')::uuid,(claim->>'fence')::uuid) from pg_temp.c5;
reset role; update private.world_npc_memory_outbox set lease_until=clock_timestamp()-interval '1 second' where id=(select (claim->>'id')::uuid from pg_temp.c5);
set local role service_role; set local request.jwt.claim.role='service_role';
create temporary table pg_temp.c5r as select public.world_npc_memory_claim('embedding','npc-embedding-accept-v1') claim;
create temporary table pg_temp.p5r as select public.world_npc_memory_embedding_plan((claim->>'id')::uuid,(claim->>'fence')::uuid) plan from pg_temp.c5r;
select is((select public.world_npc_memory_embedding_recover_dispatch((claim->>'id')::uuid,(claim->>'fence')::uuid)->>'directive' from pg_temp.c5r),'fail_only','reclaimed receipt is explicitly fail-only');
select is((select public.world_npc_memory_embedding_accept((claim->>'id')::uuid,(claim->>'fence')::uuid,'20100000-0000-4000-8000-000000000101',plan->>'inputHash',null,null,null,null,'{}'::jsonb,'provider_timeout')->>'status' from pg_temp.c5r cross join pg_temp.p5r),'failed','reclaimed current fence can terminalize a fail-only receipt');
select throws_ok(format('select public.world_npc_memory_embedding_accept(%L,%L,%L,%L,%L,3,%L::extensions.vector,%L,%L::jsonb)',(select claim->>'id' from pg_temp.c5),(select claim->>'fence' from pg_temp.c5),'20100000-0000-4000-8000-000000000101',(select plan->>'inputHash' from pg_temp.p5),'accept-model','[1,0,0]','late','{"promptTokens":1,"totalTokens":1}'),'PT409',null,'old reclaimed fence cannot later accept success');
reset role; select is((select count(*) from private.world_npc_memory_artifacts where processor_version='npc-embedding-accept-v1'),1::bigint,'acceptance creates one immutable artifact');
select * from finish(); rollback;
